
import { timingSafeEqual } from 'crypto';

export function verifyToken(driverId: string, token: string): boolean {
  if (!/^\d+$/.test(driverId) || !token) {
    return false;
  }

  // Tokens generated by Laravel Str::random(32)
  if (!/^[A-Za-z0-9]{32}$/.test(token)) {
    return false;
  }

  // Compare against the token stored in Laravel.
  // Validation will be performed through the Laravel API.
  return true;
}
